    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and result map cannot be null");
    }

    Set<V> leftPartition = new HashSet<>(resultMap.values());
    Set<V> rightPartition = new HashSet<>(resultMap.values());

    // To ensure bipartition, we need to split the vertices into two disjoint sets.
    // For simplicity, let's split them based on some criteria, e.g., hashcode % 2.
    Iterator<V> iterator = rightPartition.iterator();
    while (iterator.hasNext()) {
        V vertex = iterator.next();
        if (vertex.hashCode() % 2 == 0) {
            leftPartition.add(vertex);
            iterator.remove();
        }
    }

    // Add all vertices to the graph
    target.addAllVertices(leftPartition);
    target.addAllVertices(rightPartition);

    // Add edges between all vertices of the left and right partitions
    for (V leftVertex : leftPartition) {
        for (V rightVertex : rightPartition) {
            if (!leftVertex.equals(rightVertex)) { // Avoid self-loops
                target.addEdge(leftVertex, rightVertex);
            }
        }
    }
}

