List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    final long FETCH_DATA_DURATION = 3600000; // Example value for FETCH_DATA_DURATION in milliseconds

    if (start >= end) {
        return timeRanges; // Return empty list if start is not before end
    }

    try {
        while (start < end) {
            long rangeEnd = Math.min(start + FETCH_DATA_DURATION, end);
            timeRanges.add(new TimeRange(start, rangeEnd));
            start = rangeEnd;
        }
    } catch (Exception e) {
        // Handle any unexpected exceptions
        e.printStackTrace();
    }

    return timeRanges;
}

