long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be greater than 0");
        }
        int year = (int) (timeBucket / 10000);
        int monthDay = (int) (timeBucket % 10000);
        int month = monthDay / 100;
        int day = monthDay % 100;

        // Calculate the start day of the month
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
            daysInMonth[1] = 29; // Leap year
        }

        int dayOfYear = 0;
        for (int i = 0; i < month - 1; i++) {
            dayOfYear += daysInMonth[i];
        }
        dayOfYear += day;

        int compressedDayOfYear = (dayOfYear / dayStep) * dayStep;

        int compressedDay = 1;
        int compressedMonth = 1;
        for (int i = 0; i < 12; i++) {
            if (compressedDayOfYear <= daysInMonth[i]) {
                compressedDay = compressedDayOfYear;
                compressedMonth = i + 1;
                break;
            }
            compressedDayOfYear -= daysInMonth[i];
        }

        return year * 10000L + compressedMonth * 100L + compressedDay;
    } catch (Exception e) {
        e.printStackTrace();
        return timeBucket; // In case of any error, return the original timeBucket
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    if (timeBucket < 1000000 || timeBucket > 99991231) {
        throw new IllegalArgumentException("timeBucket must be in the format YYYYMMDD and within a valid date range");
    }

    int year = (int) (timeBucket / 10000);
    int monthDay = (int) (timeBucket % 10000);
    int month = monthDay / 100;
    int day = monthDay % 100;

    int[] monthDays = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (isLeapYear(year)) {
        monthDays[2] = 29;
    }

    int dayOfYear = 0;
    for (int i = 1; i < month; i++) {
        dayOfYear += monthDays[i];
    }
    dayOfYear += day;

    int dayInStep = dayOfYear % dayStep;
    if (dayInStep != 0) {
        dayOfYear -= dayInStep;
    }

    int newDay = 0;
    for (int i = 1; i <= 12; i++) {
        if (dayOfYear <= monthDays[i]) {
            newDay = dayOfYear;
            month = i;
            break;
        }
        dayOfYear -= monthDays[i];
    }

    String newTimeBucket = String.format("%04d%02d%02d", year, month, newDay);
    return Long.parseLong(newTimeBucket);
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the base day of the month, adjusted by dayStep
    int baseDay = (day - 1) / dayStep * dayStep + 1;

    // Reconstruct the time bucket with the base day
    return year * 10000L + month * 100L + baseDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0 || dayStep >= 100) {
        throw new IllegalArgumentException("dayStep must be between 1 and 99");
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    int daysInMonth[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (month == 2 && ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0))) {
        daysInMonth[1] = 29;
    }

    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    if (newDay > daysInMonth[month - 1]) {
        newDay = daysInMonth[month - 1];
    }

    return year * 10000L + month * 100L + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be greater than zero.");
        }
        int year = (int) (timeBucket / 10000);
        int monthDay = (int) (timeBucket % 10000);
        int day = monthDay % 100;
        int month = monthDay / 100;
        // Calculate the adjusted day based on dayStep
        int adjustedDay = (day - 1) / dayStep * dayStep + 1;
        // Handle the case where the adjusted day is out of the month's range
        if (adjustedDay > getDaysInMonth(year, month)) {
            adjustedDay = getDaysInMonth(year, month);
        }
        return year * 10000 + month * 100 + adjustedDay;
    } catch (Exception e) {
        // Log the exception or handle it as needed
        e.printStackTrace();
        return -1; // Return a sentinel value indicating an error
    }
}

int function ( CharSequence str , int index , int len ) {
    if ( str == null ) {
        throw new IllegalArgumentException( "CharSequence must not be null" );
    }
    if ( index < 0 || len < 0 || index + len > str.length() ) {
        throw new IndexOutOfBoundsException( "Invalid index or length" );
    }

    int size = 0;
    for ( int i = index; i < index + len; i++ ) {
        char c = str.charAt( i );
        if ( c <= 0x7F ) {
            size += 1;
        } else if ( c <= 0x7FF ) {
            size += 2;
        } else if ( Character.isHighSurrogate( c ) && i + 1 < index + len && Character.isLowSurrogate( str.charAt( i + 1 ) ) ) {
            size += 4;
            i++; // surrogate pair
        } else {
            size += 3;
        }
    }
    return size;
}

