int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size++;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4; // surrogate pair
                i++; // skip the next char as it is part of the surrogate pair
            } else {
                size += 3; // unpaired surrogate treated as a 3-byte sequence
            }
        } else {
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    final int end = index + len;
    try {
        for (int i = index; i < end; i++) {
            char ch = str.charAt(i);
            if (ch <= 0x007F) {
                size++;
            } else if (ch <= 0x07FF) {
                size += 2;
            } else if (Character.isHighSurrogate(ch)) {
                if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                    size += 4; // surrogate pair
                    i++; // skip next char as it is part of the surrogate pair
                } else {
                    size += 3; // unpaired high surrogate
                }
            } else {
                size += 3;
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid index or length", e);
    }
    return size;
}

