public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("str, session, and lb must not be null");
    }

    int strLen = str.length();
    int utfLen = 0;
    for (int i = 0; i < strLen; i++) {
        int c = str.charAt(i);
        if (c >= 0 && c <= 127) {
            utfLen++;
        } else if (c > 127 && c <= 2047) {
            utfLen += 2;
        } else {
            utfLen += 3;
        }
    }

    byte[] buffer = new byte[utfLen];
    int i = 0;
    int j = 0;
    while (i < strLen) {
        int c = str.charAt(i++);
        if (c >= 0 && c <= 127) {
            buffer[j++] = (byte) c;
        } else if (c > 127 && c <= 2047) {
            buffer[j++] = (byte) (0xc0 | (c >> 6));
            buffer[j++] = (byte) (0x80 | (c & 0x3f));
        } else {
            buffer[j++] = (byte) (0xe0 | (c >> 12));
            buffer[j++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            buffer[j++] = (byte) (0x80 | (c & 0x3f));
        }
    }

    return writeBytes(buffer, 0, utfLen, session, lb);
}

LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Arguments must not be null");
    }

    int length = str.length();
    int utf8Length = 0;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            utf8Length += 1;
        } else if (c < 0x800) {
            utf8Length += 2;
        } else if (Character.isSurrogate(c)) {
            i++; // Skip the next character since it is a surrogate pair
            utf8Length += 4;
        } else {
            utf8Length += 3;
        }
    }

    LinkedBuffer buffer = lb;
    int idx = buffer.start;
    int size = buffer.buffer.length;

    if (idx + utf8Length + 2 > size) { // +2 for length prefix
        buffer = allocate(buffer, utf8Length + 2);
        idx = buffer.start;
    }

    writeVarInt(utf8Length, buffer.buffer, idx);
    idx += sizeOfVarInt(utf8Length);

    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            buffer.buffer[idx++] = (byte) c;
        } else if (c < 0x800) {
            buffer.buffer[idx++] = (byte) (0xC0 | (c >> 6));
            buffer.buffer[idx++] = (byte) (0x80 | (c & 0x3F));
        } else if (Character.isSurrogate(c)) {
            i++; // Skip the next character since it is a surrogate pair
            char low = str.charAt(i);
            int codePoint = Character.toCodePoint(c, low);
            buffer.buffer[idx++] = (byte) (0xF0 | (codePoint >> 18));
            buffer.buffer[idx++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
            buffer.buffer[idx++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            buffer.buffer[idx++] = (byte) (0x80 | (codePoint & 0x3F));
        } else {
            buffer.buffer[idx++] = (byte) (0xE0 | (c >> 12));
            buffer.buffer[idx++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            buffer.buffer[idx++] = (byte) (0x80 | (c & 0x3F));
        }
    }

    buffer.start = idx;
    return buffer;
}

LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    int length = str.length();
    int utf8Len = 0;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) utf8Len += 1;
        else if (c <= 0x7FF) utf8Len += 2;
        else if (Character.isHighSurrogate(c)) {
            i++; // high surrogate - skip the next low surrogate
            utf8Len += 4;
        } else utf8Len += 3;
    }

    LinkedBuffer buffer = lb;
    int size = 0;
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            buffer.buffer[size++] = (byte) c;
        } else if (c <= 0x7FF) {
            buffer.buffer[size++] = (byte) (0xC0 | (c >>> 6));
            buffer.buffer[size++] = (byte) (0x80 | (c & 0x3F));
        } else if (Character.isHighSurrogate(c)) {
            i++; // high surrogate - skip the next low surrogate
            char lowSurrogate = str.charAt(i);
            int codePoint = Character.toCodePoint(c, lowSurrogate);
            buffer.buffer[size++] = (byte) (0xF0 | (codePoint >>> 18));
            buffer.buffer[size++] = (byte) (0x80 | ((codePoint >>> 12) & 0x3F));
            buffer.buffer[size++] = (byte) (0x80 | ((codePoint >>> 6) & 0x3F));
            buffer.buffer[size++] = (byte) (0x80 | (codePoint & 0x3F));
        } else {
            buffer.buffer[size++] = (byte) (0xE0 | (c >>> 12));
            buffer.buffer[size++] = (byte) (0x80 | ((c >>> 6) & 0x3F));
            buffer.buffer[size++] = (byte) (0x80 | (c & 0x3F));
        }
        if (size >= buffer.buffer.length) {
            buffer = buffer.next = session.nextBuffer();
            size = 0;
        }
    }
    buffer.size = size;
    return lb;
}

LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    final int strLength = str.length();
    int utfLen = 0;
    for (int i = 0; i < strLength; i++) {
        int c = str.charAt(i);
        if (c < 0x80) {
            utfLen++;
        } else if (c < 0x800) {
            utfLen += 2;
        } else if (Character.isSurrogate((char) c)) {
            utfLen += 4;
            i++; // skip the next char as well, since UTF-16 surrogate pairs are 2 chars
        } else {
            utfLen += 3;
        }
    }

    LinkedBuffer buffer = lb;
    int offset = buffer.start();
    int size = buffer.size();

    for (int i = 0; i < strLength; i++) {
        int c = str.charAt(i);
        if (offset + 5 > size) { // Ensure we have enough space, UTF-8 can take up to 4 bytes, +1 for safety
            buffer = buffer.next(session.nextBuffer());
            offset = buffer.start();
            size = buffer.size();
        }

        if (c < 0x80) {
            buffer.buffer[offset++] = (byte) c;
        } else if (c < 0x800) {
            buffer.buffer[offset++] = (byte) (0xC0 | (c >> 6));
            buffer.buffer[offset++] = (byte) (0x80 | (c & 0x3F));
        } else if (Character.isSurrogate((char) c)) {
            // Handle surrogate pairs
            char low = str.charAt(i++);
            if (!Character.isHighSurrogate((char) c) || !Character.isLowSurrogate(low)) {
                throw new IllegalArgumentException("Invalid surrogate pair");
            }
            int codePoint = Character.toCodePoint((char) c, low);
            buffer.buffer[offset++] = (byte) (0xF0 | (codePoint >> 18));
            buffer.buffer[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
            buffer.buffer[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            buffer.buffer[offset++] = (byte) (0x80 | (codePoint & 0x3F));
        } else {
            buffer.buffer[offset++] = (byte) (0xE0 | (c >> 12));
            buffer.buffer[offset++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            buffer.buffer[offset++] = (byte) (0x80 | (c & 0x3F));
        }
    }

    buffer.offset(offset);
    return buffer;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) throw new IllegalArgumentException("str cannot be null");
    if (session == null) throw new IllegalArgumentException("session cannot be null");
    if (lb == null) throw new IllegalArgumentException("lb cannot be null");

    try {
        int strlen = str.length();
        int offset = lb.start + lb.pos;
        int len = strlen;
        int st = 0;
        char c;
        int count = 0;

        while (st < strlen) {
            c = str.charAt(st++);
            if ((c >= 0x0001) && (c <= 0x007F)) {
                count++;
            } else if (c > 0x07FF) {
                count += 3;
            } else {
                count += 2;
            }
        }

        byte[] bytes = new byte[count];
        int dst = 0;

        st = 0;
        while (st < strlen) {
            c = str.charAt(st++);
            if ((c >= 0x0001) && (c <= 0x007F)) {
                bytes[dst++] = (byte) c;
            } else if (c > 0x07FF) {
                bytes[dst++] = (byte) (0xE0 | ((c >> 12) & 0x0F));
                bytes[dst++] = (byte) (0x80 | ((c >> 6) & 0x3F));
                bytes[dst++] = (byte) (0x80 | ((c >> 0) & 0x3F));
            } else {
                bytes[dst++] = (byte) (0xC0 | ((c >> 6) & 0x1F));
                bytes[dst++] = (byte) (0x80 | ((c >> 0) & 0x3F));
            }
        }

        for (byte b : bytes) {
            if (offset >= lb.limit) {
                lb = lb.next();
                offset = lb.start;
            }
            lb.buffer[offset++] = b;
            lb.pos++;
        }
        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF8 string to LinkedBuffer", e);
    }
}

