String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props cannot be null");
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    // Perform variable substitution
    StringBuilder result = new StringBuilder();
    int start = 0;
    int varStart = value.indexOf("${");
    while (varStart != -1) {
        result.append(value, start, varStart);
        int varEnd = value.indexOf('}', varStart + 2);
        if (varEnd == -1) {
            throw new IllegalArgumentException("Unterminated variable substitution: " + value);
        }
        String varKey = value.substring(varStart + 2, varEnd);
        String varValue = findAndSubst(varKey, props); // Recursively substitute the variable
        if (varValue == null) {
            throw new IllegalArgumentException("Undefined variable: " + varKey);
        }
        result.append(varValue);
        start = varEnd + 1;
        varStart = value.indexOf("${", start);
    }
    result.append(value.substring(start));
    return result.toString();
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("Key and props must not be null");
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null; // Key not found in properties
    }
    // performing variable substitution
    try {
