List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    try {
        String path = u.getRawPath();
        if (path == null || path.isEmpty()) {
            return pathSegments; // Return empty list if path is null or empty
        }

        boolean isAbsolute = path.startsWith("/");
        String[] segments = path.split("/", -1);

        int startIndex = isAbsolute ? 1 : 0; // Skip leading '/' if path is absolute
        for (int i = startIndex; i < segments.length; i++) {
            String segment = segments[i];
            if (decode) {
                segment = java.net.URLDecoder.decode(segment, "UTF-8");
            }
            pathSegments.add(new PathSegmentImpl(segment, segment.isEmpty()));
        }
    } catch (Exception e) {
        // Handle potential exceptions such as UnsupportedEncodingException
        throw new IllegalStateException("Error decoding path segments", e);
    }
    return pathSegments;
}

