            // No value to pop
            break;
        case 'Z': // boolean
        case 'C': // char
        case 'B': // byte
        case 'S': // short
        case 'I': // int
        case 'F': // float
            // Pop one value from the stack
            popValue();
            break;
        case 'J': // long
        case 'D': // double
            // Pop two values from the stack
            popValue();
            popValue();
            break;
        case 'L': // Reference type (class, interface, array, etc.)
        case '[': // Array type
            // Pop one reference from the stack
            popValue();
            break;
        case '(':
            // Method descriptor, parse the argument types and pop them
            int current = 1;
            while (descriptor.charAt(current) != ')') {
                current = parseAndPopSingleType(descriptor, current);
            }
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
