    while (index < typesToPop.length()) {
        char type = typesToPop.charAt(index);
        switch (type) {
            case 'B': // byte
            case 'C': // char
            case 'D': // double (consumes two slots)
            case 'F': // float
            case 'I': // int
            case 'S': // short
            case 'Z': // boolean
                index++;
                popOutputFrameStack();
                break;
            case 'J': // long (consumes two slots)
                index++;
                popOutputFrameStack();
                popOutputFrameStack();
                break;
            case 'L': // object reference
            case '[': // array reference
                index = typesToPop.indexOf(';', index) + 1;
                if (index == 0) {
                    throw new IllegalArgumentException("Invalid type descriptor for object or array reference");
                }
                popOutputFrameStack();
                break;
            default:
