@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == Character.class || type == char.class) {
        if (value == null) {
            throw new IllegalArgumentException("Input value cannot be null for conversion to Character.");
        }
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String strValue = (String) value;
            if (strValue.length() != 1) {
                throw new IllegalArgumentException("String value must be a single character for conversion to Character.");
            }
            return strValue.charAt(0);
        }
        if (value instanceof Number) {
            int intValue = ((Number) value).intValue();
            if (intValue < Character.MIN_VALUE || intValue > Character.MAX_VALUE) {
                throw new IllegalArgumentException("Number value is out of range for conversion to Character.");
            }
            return (char) intValue;
        }
        throw new IllegalArgumentException("Value of type " + value.getClass().getName() + " cannot be converted to Character.");
    }
    throw new IllegalArgumentException("Type " + type.getName() + " is not supported for conversion.");
}

