public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 1) {
        return 2; // The smallest prime number
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (!isPrime(candidate)) {
        candidate += 2;
    }
    if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
        // If the candidate is more than 11% greater than desiredCapacity, find the previous prime
        candidate = previousPrime(desiredCapacity);
    }
    return candidate;
}

