public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be greater than 0");
    }

    int candidate = desiredCapacity;
    if (candidate <= 2) {
        return 2;
    }

    if (candidate % 2 == 0) {
        candidate++;
    }

    while (!isPrime(candidate)) {
        candidate += 2;
    }

    if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
        candidate = findClosestPrime(desiredCapacity, desiredCapacity * 1.11);
    }

    return candidate;
}

