                contentMap.put(key, buildContent(element.getAsJsonObject()));
            } else if (element.isJsonArray()) {
                contentMap.put(key, element.getAsJsonArray().toString());
            } else if (element.isJsonPrimitive()) {
                JsonPrimitive primitive = element.getAsJsonPrimitive();
                if (primitive.isString()) {
                    String value = primitive.getAsString();
                    if (value.contains("@")) { // Assuming "@" is used to denote ats someone
                        String[] parts = value.split("@");
                        if (parts.length > 1) {
                            contentMap.put(key, value);
                            contentMap.put("ats", parts[1]);
                        } else {
                            contentMap.put(key, value);
                        }
                    } else {
                        contentMap.put(key, value);
                    }
                } else if (primitive.isNumber()) {
                    contentMap.put(key, primitive.getAsNumber());
                } else if (primitive.isBoolean()) {
                    contentMap.put(key, primitive.getAsBoolean());
                }
            } else if (element.isJsonNull()) {
                contentMap.put(key, null);
            }
        }
    }
    return contentMap;
}

