GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return new DefaultGraphPath<>();
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    try {
        for (E edge : edgeList) {
            V targetVertex = graph.getEdgeTarget(edge);
            vertexList.add(targetVertex);
        }
    } catch (Exception e) {
        throw new IllegalArgumentException("The provided set of edges does not form a valid tour in the graph.", e);
    }

    return new DefaultGraphPath<>(graph, vertexList, edgeList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>();
    }

    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    V startVertex = null;

    try {
        startVertex = graph.getEdgeSource(edgeList.get(0));
        vertexList.add(startVertex);
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid tour - could not determine start vertex", e);
    }

    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (vertexList.get(vertexList.size() - 1).equals(source)) {
            vertexList.add(target);
        } else if (vertexList.get(vertexList.size() - 1).equals(target)) {
            vertexList.add(source);
        } else {
            throw new IllegalArgumentException("Invalid tour - edges are not connected in a path");
        }
    }

    return new DefaultGraphPath<>(vertexList, edgeList);
}

GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour set and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>();
    }

    List<E> edgeList = new ArrayList<>(tour);
    DefaultGraphPath<V, E> path = new DefaultGraphPath<>();

    V startVertex = null;
    for (E edge : edgeList) {
        if (startVertex == null) {
            startVertex = graph.getEdgeSource(edge);
        }
        path.add(startVertex, edge);
        startVertex = graph.getEdgeTarget(edge);
    }

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    if (tour.isEmpty()) {
        return new DefaultGraphPath<>();
    }

    // Create a list to store the path
    List<E> pathEdges = new ArrayList<>(tour);
    List<V> pathVertices = new ArrayList<>();

    try {
        // Start with an arbitrary vertex from the first edge
        E startEdge = pathEdges.get(0);
        V startVertex = graph.getEdgeSource(startEdge);
        pathVertices.add(startVertex);

        // Reconstruct the path
        Set<E> remainingEdges = new HashSet<>(tour);
        V currentVertex = startVertex;

        while (!remainingEdges.isEmpty()) {
            E nextEdge = null;
            for (E edge : remainingEdges) {
                if (graph.getEdgeSource(edge).equals(currentVertex) || graph.getEdgeTarget(edge).equals(currentVertex)) {
                    nextEdge = edge;
                    break;
                }
            }

            if (nextEdge == null) {
                throw new IllegalArgumentException("The provided set of edges does not form a valid tour");
            }

            remainingEdges.remove(nextEdge);
            pathEdges.add(nextEdge);

            // Determine the next vertex
            V nextVertex = graph.getEdgeSource(nextEdge).equals(currentVertex) 
                           ? graph.getEdgeTarget(nextEdge) 
                           : graph.getEdgeSource(nextEdge);

            pathVertices.add(nextVertex);
            currentVertex = nextVertex;
        }

        // Ensure the path is a cycle
        if (!pathVertices.get(0).equals(pathVertices.get(pathVertices.size() - 1))) {
            throw new IllegalArgumentException("The provided set of edges does not form a valid tour");
        }

        return new DefaultGraphPath<>(graph, pathVertices, pathEdges);

    } catch (IllegalArgumentException e) {
        throw new IllegalArgumentException("Invalid input: " + e.getMessage(), e);
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, null, 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    V currentVertex = startVertex;
    List<V> vertexList = new ArrayList<>();
    vertexList.add(currentVertex);

    double totalWeight = 0.0;
    for (E edge : edgeList) {
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Tour contains edge not present in graph: " + edge);
        }
        vertexList.add(graph.getEdgeTarget(edge));
        totalWeight += graph.getEdgeWeight(edge);
        currentVertex = graph.getEdgeTarget(edge);
    }

    // Ensure the tour forms a cycle by checking if the end vertex connects back to the start
    if (!graph.containsEdge(currentVertex, startVertex)) {
        throw new IllegalArgumentException("Tour does not form a cycle");
    }

    return new GraphPathImpl<>(graph, startVertex, vertexList, totalWeight);
}

