int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }
    for (int i = 1; i < constantPool.size(); i++) {
        Symbol existing = constantPool.get(i);
        if (existing instanceof ConstantNameAndType && existing.name.equals(name) && existing.descriptor.equals(descriptor)) {
            return i;
        }
    }
    Symbol newSymbol = new ConstantNameAndType(name, descriptor);
    constantPool.add(newSymbol);
    return constantPool.size() - 1;
}

int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }
    for (int i = 1; i < this.items.length; i += 2) {
        if (this.items[i - 1] == ConstantPoolItemType.CONSTANT_NameAndType
                && name.equals(this.items[i])
                && descriptor.equals(this.items[i + 1])) {
            return i / 2;
        }
    }
    this.items = add(this.items, this.index, new Symbol(ConstantPoolItemType.CONSTANT_NameAndType, name).withValue(descriptor));
    int index = (this.index - 1) / 2;
    this.index += 2;
    return index;
}

