    }
    for (int i = 1; i < constantPool.size(); i++) {
        Object[] constant = constantPool.get(i);
        if (constant[0] == ConstantPool.CONSTANT_NameAndType &&
            constant[1].equals(name) &&
            constant[2].equals(descriptor)) {
            return i;
        }
    }
    constantPool.add(new Object[]{ConstantPool.CONSTANT_NameAndType, name, descriptor});
    return constantPool.size() - 1;
}

