private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    boolean escapeMode = false;
    for (char c : input.toCharArray()) {
        if (escapeMode) {
            if (c == '\\' || c == '.') {
                result.append(c);
            } else {
                result.append('\\').append(c);
            }
            escapeMode = false;
        } else if (c == '\\') {
            escapeMode = true;
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < input.length()) {
                char nextChar = input.charAt(i + 1);
                if (nextChar == 'u') {
                    // Handle Unicode escape sequence
                    if (i + 5 < input.length()) {
                        try {
                            result.append((char) Integer.parseInt(input.substring(i + 2, i + 6), 16));
                            i += 5; // Skip the Unicode escape sequence
                        } catch (NumberFormatException e) {
                            // Invalid Unicode escape, treat as literal chars
                            result.append("\\u").append(input, i + 2, i + 6);
                            i += 5;
                        }
                    } else {
                        // Not enough characters for a Unicode escape, treat as literals
                        result.append("\\u").append(input.substring(i + 1));
                        break;
                    }
                } else {
                    // Handle other escape sequences
                    switch (nextChar) {
                        case 'b':
                            result.append('\b');
                            break;
                        case 'f':
                            result.append('\f');
                            break;
                        case 'n':
                            result.append('\n');
                            break;
                        case 'r':
                            result.append('\r');
                            break;
                        case 't':
                            result.append('\t');
                            break;
                        default:
                            result.append(nextChar);
                            break;
                    }
                    i++;
                }
            } else {
                // Trailing backslash, treat as literal
                result.append(c);
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    boolean isEscaped = false;
    for (char c : input.toCharArray()) {
        if (isEscaped) {
            if (c == '.' || c == ' ') {
                result.append(c);
            } else {
                result.append('\\').append(c);
            }
            isEscaped = false;
        } else if (c == '\\') {
            isEscaped = true;
        } else {
            result.append(c);
        }
    }
    if (isEscaped) {
        result.append('\\');
    }
    return result.toString();
}

