private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    Set<Integer> fromBucket = bucketsByLabel.get(minLabel);
    if (fromBucket == null) {
        return; // No vertices to move
    }

    Set<Integer> toBucket = bucketsByLabel.get(0);
    if (toBucket == null) {
        toBucket = new HashSet<>();
        bucketsByLabel.set(0, toBucket);
    }

    for (Integer vertex : fromBucket) {
        labels.set(vertex, 0);
        toBucket.add(vertex);
    }

    fromBucket.clear();
}

