private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices must not be null");
    }
    if (vertices.size() <= 1) {
        return true; // A single vertex or empty set is trivially a clique
    }
    for (V vertex1 : vertices) {
        if (!graph.containsVertex(vertex1)) {
            throw new IllegalArgumentException("All vertices must be in the graph");
        }
        for (V vertex2 : vertices) {
            if (!vertex1.equals(vertex2) && !graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices must not be null");
    }
    if (vertices.isEmpty()) {
        return true; // An empty set is trivially a clique
    }

    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            throw new IllegalArgumentException("Vertex " + vertex + " is not in the graph");
        }
    }

    int vertexCount = vertices.size();
    for (V vertex : vertices) {
        Set<V> neighbors = new HashSet<>(Graphs.neighborListOf(graph, vertex));
        neighbors.retainAll(vertices); // Get neighbors that are in the specified set
        if (neighbors.size() != vertexCount - 1) {
            return false; // Not all other vertices are neighbors
        }
    }
    return true;
}

