private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    // Check if the descriptor is a method descriptor
    if (descriptor.charAt(0) == '(') {
        int endParen = descriptor.indexOf(')');
        if (endParen == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        String argsDescriptor = descriptor.substring(1, endParen);
        int i = 0;
        while (i < argsDescriptor.length()) {
            char c = argsDescriptor.charAt(i);
            switch (c) {
                case 'B': case 'C': case 'I': case 'S': case 'Z':
                    // These types take up one slot
                    i++;
                    break;
                case 'D': case 'J':
                    // These types take up two slots
                    i += 2;
                    break;
                case 'L':
                    // Reference type, skip till ';'
                    int semicolonIndex = argsDescriptor.indexOf(';', i);
                    if (semicolonIndex == -1) {
                        throw new IllegalArgumentException("Invalid reference type in descriptor");
                    }
                    i = semicolonIndex + 1;
                    break;
                case '[':
                    // Array type, skip to the end of the array descriptor
                    do {
                        i++;
                        c = argsDescriptor.charAt(i);
                    } while (c == '[');
                    if (c == 'L') {
                        // If it's an object array, skip till ';'
                        int arraySemicolonIndex = argsDescriptor.indexOf(';', i);
                        if (arraySemicolonIndex == -1) {
                            throw new IllegalArgumentException("Invalid reference type in array descriptor");
                        }
                        i = arraySemicolonIndex + 1;
                    } else {
                        i++;
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid character in descriptor: " + c);
            }
        }
    } else {
        // It's a field descriptor, pop accordingly
        switch (descriptor.charAt(0)) {
            case 'B': case 'C': case 'I': case 'S': case 'Z':
                // These types take up one slot
                break;
            case 'D': case 'J':
                // These types take up two slots
                break;
            case 'L':
                // Reference type, skip till ';'
                if (descriptor.indexOf(';') != descriptor.length() - 1) {
                    throw new IllegalArgumentException("Invalid reference type in field descriptor");
                }
                break;
            case '[':
                // Array type, already handled correctly by the length check
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

